// Находим все контейнеры с для отображение скрытых блоков
const showItems = document.querySelectorAll(".show__items");
if (showItems.length > 0) {

    const aktsiiItems = document.querySelectorAll(".aktsii-page__items");
    const reviewsItems = document.querySelectorAll(".reviews__cards");
    const photosItems = document.querySelectorAll(".photos__items");
    console.log(showItems.length);
    let visibleCount = 0;
    if (aktsiiItems.length > 0) {
        visibleCount = 16;
    } else if (reviewsItems.length > 0) {
        visibleCount = 15;
    } else if (photosItems.length > 0) {
        visibleCount = 20;
    } else {
        visibleCount = 16;
    }
    showItems.forEach((container) => {
        const showItem = Array.from(container.querySelectorAll(".show__item"));
        const btn = container.parentElement.querySelector(".show__item-btn");
        // предполагаем, что кнопка находится рядом (в родителе контейнера)

        if (!showItem.length || !btn) return; // если элементов или кнопки нет — пропускаем

        let expanded = false;

        if (showItem.length > visibleCount) {
            // Скрываем всё, что идёт после 16-го
            const hideExtraItems = () => {
                showItem.forEach((item, index) => {
                    item.classList.toggle("hidden", index >= visibleCount);

                });
            };

            // Показываем все акции
            const showAllItems = () => {
                showItem.forEach((item) => item.classList.remove("hidden"));
            };

            // Переключение состояния
            const toggleAktsii = () => {
                if (expanded) {
                    hideExtraItems();
                    btn.classList.remove("open");
                } else {
                    showAllItems();
                    btn.classList.add("open");
                }
                expanded = !expanded;
            };

            // Изначально скрываем лишние карточки
            hideExtraItems();

            // Обработчик клика
            btn.addEventListener("click", toggleAktsii);
        } else {
            btn.classList.add("hidden");
        }

    });
}
