/* yandex map */
const map = document.querySelectorAll('#map');
let mapInitialized = false; // Флаг для отслеживания инициализации

if (map.length > 0) {
    function onEntryMap(e) {
        e.forEach(e => {
            if (e.isIntersecting && !mapInitialized) {
                loadMap();
            }
        })
    }
    let options = {
        threshold: [0.5],
    },
        observer = new IntersectionObserver(onEntryMap, options)
    for (let e of map) observer.observe(e)
}

function loadMap() {
    if (!document.querySelector('[src*="api-maps.yandex.ru"]')) {
        const script = document.createElement('script');
        script.type = 'text/javascript';
        script.src = 'https://api-maps.yandex.ru/2.1/?apikey=72e5e5d1-9dd9-4b6e-baf4-ed40a38165e8&lang=ru_RU';
        script.onload = initMap;
        document.head.appendChild(script);
    } else if (typeof ymaps !== 'undefined' && !mapInitialized) {
        // Если скрипт уже загружен, но карта не инициализирована
        initMap();
    }
}

function initMap() {
    if (mapInitialized) return; // Защита от повторной инициализации

    ymaps.ready(function () {
        const screenWidth = window.screen.width
        let iconImageSizeX = 140;
        let iconImageSizeY = 140;
        console.log(screenWidth);
        if (screenWidth <= 1200) {
            iconImageSizeX = 60;
            iconImageSizeY = 60;
        }
        var myMap = new ymaps.Map("map", {
            center: [53.507852, 49.420411],
            zoom: 10
        }, {
            searchControlProvider: 'yandex#search'
        }),
            myPlacemark = new ymaps.Placemark(myMap.getCenter(), {
                hintContent: 'Астра',
                balloonContent: 'Астра'
            }, {
                iconLayout: 'default#image',
                iconImageSize: [iconImageSizeX, iconImageSizeY],
                iconImageOffset: [-15, -31],
                iconImageHref: '/assets/img/icons/mapEll.svg',
            });
        myMap.behaviors.disable('drag');
        myMap.geoObjects.add(myPlacemark);
        myMap.behaviors.disable(['scrollZoom']);

        mapInitialized = true; // Помечаем карту как инициализированную
    });
}
