document.addEventListener('DOMContentLoaded', function () {
    const reviewsCardBtn = document.querySelectorAll('.reviews__card-btn');
    if (reviewsCardBtn.length > 0) {
        reviewsCardBtn.forEach((btn) => {
            btn.addEventListener('click', () => {
                const card = btn.closest('.reviews__card');
                const mainText = card.querySelector('.reviews__card-main').textContent.trim();
                const popupContent = document.querySelector('.popup__content-text');
                popupContent.textContent = mainText;
            })
        });
    }

    const tabButtons = document.querySelectorAll('.tab-btn');
    const tabContents = document.querySelectorAll('.tab-content');
    const containerBtns = document.querySelector(".tab-btns");

    if (tabButtons.length > 0 && tabContents.length > 0) {
        tabButtons.forEach((btn) => {
            btn.addEventListener("click", () => {
                const target = btn.dataset.tab;
                if (btn.classList.contains("open")) {
                    tabButtons.forEach((b) => b.classList.remove("open"));
                } else {
                    tabButtons.forEach((b) => b.classList.add("open"));
                }
                tabButtons.forEach((b) => b.classList.remove("active"));

                btn.classList.add("active")

                screenWidth = window.screen.width;
                console.log(screenWidth);
                if (screenWidth <= 1200) {
                    containerBtns.prepend(btn);
                }

                tabContents.forEach((content) => {
                    if (content.dataset.tab == target) {
                        content.classList.add("active");
                    } else {
                        content.classList.remove("active");
                    }
                })
            });
        })
    }
    const tabButton = document.querySelectorAll('.tab__btn');
    const tabContent = document.querySelectorAll('.tab__content');
    const containerBtn = document.querySelector(".tab__btns");

    if (tabButton.length > 0 && tabContent.length > 0) {
        tabButton.forEach((btn) => {
            btn.addEventListener("click", () => {
                const target = btn.dataset.tab;
                if (btn.classList.contains("open")) {
                    tabButton.forEach((b) => b.classList.remove("open"));
                } else {
                    tabButton.forEach((b) => b.classList.add("open"));
                }
                tabButton.forEach((b) => b.classList.remove("active"));

                btn.classList.add("active")

                screenWidth = window.screen.width;
                tabContent.forEach((content) => {
                    if (content.dataset.tab == target) {
                        content.classList.add("active");
                    } else {
                        content.classList.remove("active");
                    }
                })
            });
        })
    }

    const sortBtns = document.querySelectorAll(".sort-btn");
    const containerCards = document.querySelectorAll(".reviews__cards");

    if (containerCards && sortBtns.length > 0) {
        sortBtns.forEach((btn) => {
            btn.addEventListener("click", () => {
                const target = btn.dataset.tab;
                sortBtns.forEach((b) => b.classList.remove("active"));
                btn.classList.add("active");

                containerCards.forEach((container) => {
                    const cardItems = Array.from(container.querySelectorAll(".reviews__card"));
                    const parseDate = (text) => {
                        const months = {
                            "января": 0, "февраля": 1, "марта": 2, "апреля": 3,
                            "мая": 4, "июня": 5, "июля": 6, "августа": 7,
                            "сентября": 8, "октября": 9, "ноября": 10, "декабря": 11
                        };

                        const [day, monthWord, year] = text.trim().split(/\s+/);
                        const month = months[monthWord.toLowerCase()];
                        return new Date(year, month, parseInt(day, 10));
                    };

                    if (cardItems.length === 0) return;

                    if (target == 'new') {
                        cardItems.sort((a, b) => {
                            const dateA = parseDate(a.querySelector(".reviews__card-date").textContent);
                            const dateB = parseDate(b.querySelector(".reviews__card-date").textContent);
                            return dateB - dateA;
                        });
                    } else {
                        cardItems.sort((a, b) => {
                            const dateA = parseDate(a.querySelector(".reviews__card-date").textContent);
                            const dateB = parseDate(b.querySelector(".reviews__card-date").textContent);
                            return dateA - dateB;
                        });
                    }

                    container.innerHTML = "";
                    cardItems.forEach(card => container.appendChild(card));
                });
            });
        });
    }
});

document.addEventListener('DOMContentLoaded', function () {
    const calculatorItems = document.querySelectorAll(".calculator__items")
    if (calculatorItems.length > 0) {
        calculatorItems.forEach((items) => {
            const calculatorItem = items.querySelectorAll(".calculator__item")
            calculatorItem.forEach((item) => {
                const selectOption = item.querySelectorAll(".select__option")
                const selectTrigger = item.querySelector(".select__trigger")
                const selectPriceTitle = item.querySelector(".calculator__item-price")
                selectOption.forEach((value) => {
                    value.addEventListener('click', () => {
                        triggerAttribute = value.getAttribute('data-value');
                        selectTrigger.setAttribute('data-value', triggerAttribute);
                        selectTrigger.classList.add('changed');
                        selectTrigger.textContent = value.querySelector('.option__text').textContent;
                        if (value.querySelector('.option__num')) {
                            selectPriceTitle.textContent = value.querySelector('.option__num').textContent;
                        }
                        if (value.querySelector('.option__checkbox')) {
                            if (value.classList.contains('changed')) {
                                value.classList.remove('changed');
                            } else {
                                value.classList.add('changed');
                            }
                            if (value.classList.contains('select__option--all') && value.classList.contains('changed')) {
                                selectOption.forEach((e) => e.classList.add('changed'));
                            }
                            if (value.classList.contains('select__option--all') && value.classList.contains('changed') == false) {
                                selectOption.forEach((e) => e.classList.remove('changed'));
                            }
                        }
                        if (value.querySelector('.option__num') && value.querySelector('.option__checkbox')) {
                            var sum = 0;
                            selectOption.forEach((e) => {
                                const numEl = e.querySelector('.option__num');
                                if (numEl && e.classList.contains('changed') == false) {
                                    let num = parseInt(numEl.textContent.replace(/\D/g, '')) || 0;
                                    sum += num;
                                }
                                if (sum == 0) {
                                    selectPriceTitle.textContent = '';
                                } else {
                                    selectPriceTitle.textContent = '+' + sum;
                                }
                            });
                        }
                    });
                });

            });
        });
    }
});